+#include "hotspotselection.h"
+
+namespace HotspotSelection
+{
+
+Suitability suitability(const DeviceProperties &device)
+{
+    if (device.unused) {
+        return device.apCapable ? UnusedAccessPoint : UnusedAdHoc;
+    }
+
+    if (device.reusable) {
+        return device.apCapable ? ReusableAccessPoint : ReusableAdHoc;
+    }
+
+    return Unusable;
+}
+
+bool usesApMode(Suitability suitability)
+{
+    return suitability == UnusedAccessPoint || suitability == ReusableAccessPoint;
+}
+
+Result selectDevice(const QList<DeviceProperties> &devices)
+{
+    Result result;
+
+    for (int i = 0; i < devices.size(); ++i) {
+        const Suitability deviceSuitability = suitability(devices.at(i));
+        if (deviceSuitability > result.suitability) {
+            result.index = i;
+            result.suitability = deviceSuitability;
+        }
+    }
+
+    return result;
+}
+
+}
