+/*
+    SPDX-FileCopyrightText: 2026 Aditya Srivastava <1606aditya@gmail.com>
+
+    SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+*/
+
+#ifndef PLASMA_NM_HOTSPOT_SELECTION_H
+#define PLASMA_NM_HOTSPOT_SELECTION_H
+
+#include <QList>
+
+/**
+ * Picking the wireless device which is going to host a hotspot.
+ *
+ * The logic is kept free of NetworkManager types so that both the "can a hotspot
+ * be created at all" check and the actual hotspot creation can share it, and so
+ * that it can be tested without a NetworkManager instance.
+ */
+namespace HotspotSelection
+{
+
+/**
+ * The properties of a wireless device which decide whether it can host a hotspot.
+ */
+struct DeviceProperties {
+    /** The device can be put into access point mode. */
+    bool apCapable = false;
+    /** The device is managed, available, and not used by any connection. */
+    bool unused = false;
+    /**
+     * The device is in use, but not by the connection providing default connectivity,
+     * so it can be taken over without cutting the machine off the internet.
+     */
+    bool reusable = false;
+};
+
+/**
+ * How well suited a device is for hosting a hotspot, the bigger the better.
+ *
+ * An unused device is preferred over a device which is in use, because taking over
+ * a device tears down the connection it currently carries. Access point mode is
+ * preferred over ad-hoc mode, which only exists as a fallback for devices which
+ * cannot act as an access point.
+ */
+enum Suitability {
+    Unusable = 0,
+    ReusableAdHoc,
+    ReusableAccessPoint,
+    UnusedAdHoc,
+    UnusedAccessPoint,
+};
+
+/**
+ * The device picked out of a list of candidates.
+ */
+struct Result {
+    /** Index into the list which was passed in, or -1 if no device can host a hotspot. */
+    int index = -1;
+    Suitability suitability = Unusable;
+};
+
+/**
+ * Returns how well suited @p device is for hosting a hotspot.
+ */
+Suitability suitability(const DeviceProperties &device);
+
+/**
+ * Returns whether a hotspot on a device with this @p suitability is set up as an
+ * access point, as opposed to falling back to an ad-hoc network.
+ */
+bool usesApMode(Suitability suitability);
+
+/**
+ * Returns the best suited device out of @p devices, preserving the order of the
+ * list for devices which are equally suited.
+ */
+Result selectDevice(const QList<DeviceProperties> &devices);
+
+}
+
+#endif // PLASMA_NM_HOTSPOT_SELECTION_H
