@@ -0,0 +1,129 @@
+/*
+    SPDX-FileCopyrightText: 2026 Aditya Srivastava <1606aditya@gmail.com>
+
+    SPDX-License-Identifier: GPL-2.0-only OR GPL-3.0-only OR LicenseRef-KDE-Accepted-GPL
+*/
+
+#include "hotspotselection.h"
+
+#include <QTest>
+
+Q_DECLARE_METATYPE(HotspotSelection::DeviceProperties)
+Q_DECLARE_METATYPE(HotspotSelection::Suitability)
+
+using namespace HotspotSelection;
+
+// The device carrying the connection which provides default connectivity
+static DeviceProperties primaryDevice(bool apCapable = true)
+{
+    return DeviceProperties{apCapable, false, false};
+}
+
+// A device connected to a network which is not used for default connectivity
+static DeviceProperties secondaryDevice(bool apCapable = true)
+{
+    return DeviceProperties{apCapable, false, true};
+}
+
+// A device which is available but not connected to anything
+static DeviceProperties unusedDevice(bool apCapable = true)
+{
+    return DeviceProperties{apCapable, true, false};
+}
+
+// A device which is unmanaged, rfkilled, or otherwise not available
+static DeviceProperties unavailableDevice()
+{
+    return DeviceProperties{true, false, false};
+}
+
+class HotspotSelectionTest : public QObject
+{
+    Q_OBJECT
+
+private Q_SLOTS:
+    void testSelectDevice();
+    void testSelectDevice_data();
+    void testUsesApMode();
+    void testUsesApMode_data();
+};
+
+void HotspotSelectionTest::testSelectDevice_data()
+{
+    QTest::addColumn<QList<DeviceProperties>>("devices");
+    QTest::addColumn<int>("expectedIndex");
+    QTest::addColumn<Suitability>("expectedSuitability");
+
+    QTest::newRow("no wireless device") << QList<DeviceProperties>{} << -1 << Unusable;
+
+    QTest::newRow("only device is the uplink") << QList<DeviceProperties>{primaryDevice()} << -1 << Unusable;
+
+    QTest::newRow("only device is unavailable") << QList<DeviceProperties>{unavailableDevice()} << -1 << Unusable;
+
+    QTest::newRow("single unused device") << QList<DeviceProperties>{unusedDevice()} << 0 << UnusedAccessPoint;
+
+    // The device is connected, but the internet comes in over ethernet, so it can be taken over
+    QTest::newRow("single device, wired uplink") << QList<DeviceProperties>{secondaryDevice()} << 0 << ReusableAccessPoint;
+
+    // The actual multi radio bug: one radio is the uplink, the other one is connected to a second
+    // network and can host the hotspot
+    QTest::newRow("two connected radios") << QList<DeviceProperties>{primaryDevice(), secondaryDevice()} << 1 << ReusableAccessPoint;
+
+    QTest::newRow("two connected radios, uplink last") << QList<DeviceProperties>{secondaryDevice(), primaryDevice()} << 0 << ReusableAccessPoint;
+
+    // Taking over a device tears down the connection it carries, so an unused device wins
+    QTest::newRow("unused device beats connected device") << QList<DeviceProperties>{secondaryDevice(), unusedDevice()} << 1 << UnusedAccessPoint;
+
+    QTest::newRow("unused device beats uplink") << QList<DeviceProperties>{primaryDevice(), unusedDevice()} << 1 << UnusedAccessPoint;
+
+    // Ad-hoc mode is the fallback for devices which cannot act as an access point
+    QTest::newRow("single unused device without AP support") << QList<DeviceProperties>{unusedDevice(false)} << 0 << UnusedAdHoc;
+
+    QTest::newRow("AP capable device beats ad-hoc only device")
+        << QList<DeviceProperties>{unusedDevice(false), unusedDevice(true)} << 1 << UnusedAccessPoint;
+
+    // ... but not at the price of tearing down a connection
+    QTest::newRow("unused ad-hoc only device beats connected AP capable device")
+        << QList<DeviceProperties>{secondaryDevice(true), unusedDevice(false)} << 1 << UnusedAdHoc;
+
+    QTest::newRow("connected ad-hoc only device") << QList<DeviceProperties>{primaryDevice(), secondaryDevice(false)} << 1 << ReusableAdHoc;
+
+    // Equally suited devices are picked in the order NetworkManager reports them
+    QTest::newRow("first of two unused devices") << QList<DeviceProperties>{unusedDevice(), unusedDevice()} << 0 << UnusedAccessPoint;
+}
+
+void HotspotSelectionTest::testSelectDevice()
+{
+    QFETCH(QList<DeviceProperties>, devices);
+    QFETCH(int, expectedIndex);
+    QFETCH(Suitability, expectedSuitability);
+
+    const Result result = selectDevice(devices);
+
+    QCOMPARE(result.index, expectedIndex);
+    QCOMPARE(result.suitability, expectedSuitability);
+}
+
+void HotspotSelectionTest::testUsesApMode_data()
+{
+    QTest::addColumn<Suitability>("suitability");
+    QTest::addColumn<bool>("expected");
+
+    QTest::newRow("unusable") << Unusable << false;
+    QTest::newRow("reusable ad-hoc") << ReusableAdHoc << false;
+    QTest::newRow("reusable access point") << ReusableAccessPoint << true;
+    QTest::newRow("unused ad-hoc") << UnusedAdHoc << false;
+    QTest::newRow("unused access point") << UnusedAccessPoint << true;
+}
+
+void HotspotSelectionTest::testUsesApMode()
+{
+    QFETCH(Suitability, suitability);
+    QFETCH(bool, expected);
+
+    QCOMPARE(usesApMode(suitability), expected);
+}
+
+QTEST_GUILESS_MAIN(HotspotSelectionTest)
+
+#include "hotspotselectiontest.moc"
